'use client';

import { useState, useMemo } from 'react';
import {
  Table,
  TableHeader,
  TableRow,
  TableHead,
  TableBody,
  TableCell,
} from '@/components/ui/table';
import {
  DropdownMenu,
  DropdownMenuTrigger,
  DropdownMenuContent,
  DropdownMenuItem,
} from '@/components/ui/dropdown-menu';
import { Button } from '@/components/ui/button';
import { MoreHorizontal, ChevronDown } from 'lucide-react';
import { Badge } from '@/components/ui/badge';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import {
  Collapsible,
  CollapsibleContent,
  CollapsibleTrigger,
} from "@/components/ui/collapsible"
import { useUser, useFirestore, useCollection, useMemoFirebase } from '@/firebase';
import { collection, doc } from 'firebase/firestore';
import type { Project, LineItem } from '@/lib/types';
import { Skeleton } from '@/components/ui/skeleton';
import { useToast } from '@/hooks/use-toast';
import { deleteDocumentNonBlocking } from '@/firebase/non-blocking-updates';


function ProjectLineItems({ userId, projectId }: { userId: string, projectId: string }) {
  const firestore = useFirestore();
  const lineItemsQuery = useMemoFirebase(() => {
    if (!userId || !projectId) return null;
    return collection(firestore, 'users', userId, 'projectEstimates', projectId, 'estimateLineItems');
  }, [firestore, userId, projectId]);
  const { data: lineItems, isLoading } = useCollection<LineItem>(lineItemsQuery);

  if (isLoading) {
    return (
        <div className="px-4">
            <Table>
                <TableHeader>
                    <TableRow>
                    <TableHead>Description</TableHead>
                    <TableHead className="text-right">Cost</TableHead>
                    </TableRow>
                </TableHeader>
                <TableBody>
                    {[...Array(3)].map((_, i) => (
                    <TableRow key={i}>
                        <TableCell><Skeleton className="h-4 w-[100px]" /></TableCell>
                        <TableCell className="text-right"><Skeleton className="h-4 w-[60px] ml-auto" /></TableCell>
                    </TableRow>
                    ))}
                </TableBody>
            </Table>
        </div>
    )
  }

  if (!lineItems || lineItems.length === 0) {
    return <p className="text-sm text-muted-foreground text-center py-4">No line items for this project.</p>
  }

  return (
    <div className="px-4">
        <Table>
        <TableHeader>
            <TableRow>
            <TableHead>Description</TableHead>
            <TableHead className="text-right">Cost</TableHead>
            </TableRow>
        </TableHeader>
        <TableBody>
            {lineItems?.map((item) => (
            <TableRow key={item.id}>
                <TableCell>{item.description}</TableCell>
                <TableCell className="text-right">{new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 0 }).format(item.totalCost)}</TableCell>
            </TableRow>
            ))}
        </TableBody>
        </Table>
    </div>
  )
}


export default function ProjectsPage() {
  const { user, isUserLoading } = useUser();
  const firestore = useFirestore();
  const { toast } = useToast();
  const [openProjectId, setOpenProjectId] = useState<string | null>(null);

  const projectsQuery = useMemoFirebase(() => {
    if (!user) return null;
    return collection(firestore, 'users', user.uid, 'projectEstimates');
  }, [firestore, user]);

  const { data: projects, isLoading: areProjectsLoading } = useCollection<Project>(projectsQuery);

  const sortedProjects = useMemo(() => {
    return projects ? [...projects].sort((a, b) => new Date(b.createdDate).getTime() - new Date(a.createdDate).getTime()) : [];
  }, [projects]);


  const isLoading = isUserLoading || areProjectsLoading;

  const handleDeleteProject = (projectId: string) => {
    if (!user) {
      toast({ variant: 'destructive', title: 'Error', description: 'You must be logged in to delete a project.' });
      return;
    };
    
    // NOTE: This deletes the project document, but not the 'estimateLineItems' subcollection.
    // For a complete cleanup, a Cloud Function would be needed to handle cascading deletes.
    const projectRef = doc(firestore, 'users', user.uid, 'projectEstimates', projectId);
    deleteDocumentNonBlocking(projectRef);

    toast({
        title: 'Project Deleted',
        description: 'The project estimate has been removed.',
    });
  }

  return (
    <div className="flex-1 space-y-4 p-4 md:p-8 pt-6">
      <div className="flex items-center justify-between space-y-2">
        <h1 className="text-3xl font-bold tracking-tight font-headline">Projects</h1>
      </div>
       <Card>
        <CardHeader>
          <CardTitle>All Project Estimates</CardTitle>
          <CardDescription>
            Manage and review all your saved budget estimates.
          </CardDescription>
        </CardHeader>
        <CardContent>
          {/* --- DESKTOP VIEW --- */}
          <Table className="hidden md:table">
            <TableHeader>
              <TableRow>
                <TableHead>Project Name</TableHead>
                <TableHead>Estimated Budget</TableHead>
                <TableHead>Date Created</TableHead>
                <TableHead>
                  <span className="sr-only">Actions</span>
                </TableHead>
              </TableRow>
            </TableHeader>
            
            {isLoading && (
              <TableBody>
                {[...Array(3)].map((_, i) => (
                   <TableRow key={i}>
                      <TableCell><Skeleton className="h-4 w-[250px]" /></TableCell>
                      <TableCell><Skeleton className="h-4 w-[100px]" /></TableCell>
                      <TableCell><Skeleton className="h-4 w-[100px]" /></TableCell>
                      <TableCell><div className='flex items-center justify-end'><Skeleton className="h-8 w-[68px]" /></div></TableCell>
                   </TableRow>
                ))}
              </TableBody>
            )}
            {!isLoading && sortedProjects.map((project) => (
              <Collapsible asChild key={project.id}>
                <TableBody className='border-b'>
                  <TableRow>
                    <TableCell className="font-medium">{project.projectName}</TableCell>
                    <TableCell>
                      <Badge variant="outline">{new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 0 }).format(project.totalBudget)}</Badge>
                    </TableCell>
                    <TableCell>
                      {new Date(project.createdDate).toLocaleDateString()}
                    </TableCell>
                    <TableCell className="text-right">
                       <div className='flex items-center justify-end'>
                        <CollapsibleTrigger asChild>
                          <Button variant="ghost" size="icon" className='h-8 w-8 data-[state=open]:bg-accent'>
                            <ChevronDown className="h-4 w-4 transition-transform data-[state=open]:rotate-180" />
                            <span className="sr-only">Toggle details</span>
                          </Button>
                        </CollapsibleTrigger>
                        <DropdownMenu>
                          <DropdownMenuTrigger asChild>
                            <Button aria-haspopup="true" size="icon" variant="ghost" className='h-8 w-8'>
                              <MoreHorizontal className="h-4 w-4" />
                              <span className="sr-only">Toggle menu</span>
                            </Button>
                          </DropdownMenuTrigger>
                          <DropdownMenuContent align="end">
                            <DropdownMenuItem className="text-destructive" onClick={() => handleDeleteProject(project.id)}>
                              Delete
                            </DropdownMenuItem>
                          </DropdownMenuContent>
                        </DropdownMenu>
                       </div>
                    </TableCell>
                  </TableRow>
                  <CollapsibleContent asChild>
                    <TableRow className="bg-muted/50 hover:bg-muted/50">
                      <TableCell colSpan={4} className="p-0">
                        <div className="py-6">
                          <h4 className="font-semibold mb-4 px-6">Line Items</h4>
                          {user && <ProjectLineItems userId={user.uid} projectId={project.id} />}
                        </div>
                      </TableCell>
                    </TableRow>
                  </CollapsibleContent>
                </TableBody>
              </Collapsible>
            ))}
          </Table>

          {/* --- MOBILE VIEW --- */}
          <div className="space-y-4 md:hidden">
            {isLoading && [...Array(3)].map((_, i) => (
                <Card key={i}>
                    <CardContent className="p-4 space-y-3">
                        <Skeleton className="h-5 w-3/4" />
                        <Skeleton className="h-5 w-1/3" />
                        <Skeleton className="h-4 w-1/2" />
                    </CardContent>
                </Card>
            ))}
            {!isLoading && sortedProjects.map(project => (
                <Card key={project.id} className="w-full">
                <Collapsible open={openProjectId === project.id} onOpenChange={() => setOpenProjectId(openProjectId === project.id ? null : project.id)}>
                    <div className="p-4">
                        <div className="flex justify-between items-start">
                            <div className="space-y-2 flex-1 pr-4">
                                <p className="font-semibold leading-tight">{project.projectName}</p>
                                <Badge variant="outline">{new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 0 }).format(project.totalBudget)}</Badge>
                                <p className="text-sm text-muted-foreground pt-1">
                                    {new Date(project.createdDate).toLocaleDateString()}
                                </p>
                            </div>
                            <div className="flex">
                                <CollapsibleTrigger asChild>
                                    <Button variant="ghost" size="icon" className="h-8 w-8 data-[state=open]:bg-accent">
                                        <ChevronDown className="h-4 w-4 transition-transform data-[state=open]:rotate-180" />
                                        <span className="sr-only">Toggle details</span>
                                    </Button>
                                </CollapsibleTrigger>
                                <DropdownMenu>
                                <DropdownMenuTrigger asChild>
                                    <Button aria-haspopup="true" size="icon" variant="ghost" className='h-8 w-8 flex-shrink-0'>
                                    <MoreHorizontal className="h-4 w-4" />
                                    <span className="sr-only">Toggle menu</span>
                                    </Button>
                                </DropdownMenuTrigger>
                                <DropdownMenuContent align="end">
                                    <DropdownMenuItem className="text-destructive" onClick={() => handleDeleteProject(project.id)}>
                                    Delete
                                    </DropdownMenuItem>
                                </DropdownMenuContent>
                                </DropdownMenu>
                            </div>
                        </div>
                    </div>
                    <CollapsibleContent>
                      <div className="pb-4">
                        {user && <ProjectLineItems userId={user.uid} projectId={project.id} />}
                      </div>
                    </CollapsibleContent>
                </Collapsible>
              </Card>
            ))}
          </div>

           {!isLoading && (!projects || projects.length === 0) && (
              <div className="text-center p-8 text-muted-foreground">
                You haven&apos;t saved any projects yet. Create one on the &quot;New Estimate&quot; page.
              </div>
            )}
        </CardContent>
      </Card>
    </div>
  );
}
